-- Phase 263 prod EXPLAIN: the foreign blunder draw (D-01, D-05, D-14), plan 263-10.
--
-- Run by the orchestrator through the read-only prod MCP before the squash-merge (every statement
-- below is a pure SELECT over existing tables, so none of them needs the deploy), and once more
-- after the deploy as confirmation. Run each statement twice, cold (the draw samples different
-- pages each time, so the cold number is the honest one), and report: execution time, buffer
-- reads, and the row count of each statement.
--
-- Latency budget (orchestrator ruling 2, revised): step one (the band draw) at most 0.5 s cold,
-- both steps together at most 1.5 s cold. A miss blocks the squash-merge and goes back to planning.
-- Compare with 263-RESEARCH.md "Prod EXPLAIN results": the CTE alone at system(0.1) took 91 ms
-- (344 page reads, about 800 band games at level 1500); stage two about 400 ms cold; system(20.0)
-- nearest-first took 14.9 s there, which is why step two uses system(0.4).
--
-- Compiled from foreign_band_candidates_stmt / foreign_nearest_candidates_stmt (app/services/train_pool.py)
-- with PostgreSQL literal binds, the production FOREIGN_FILLER_DRAW_STEPS sample percents, the
-- game limit foreign_game_limit(5) = 40 (a default six-puzzle session with one red herring),
-- raw bounds from foreign_raw_bounds, and solver id 28. Statements were compiled, not hand-written.
-- EXPLAIN (ANALYZE, BUFFERS) executes the statement: they are read-only, run them in a READ ONLY transaction.

-- Statement 1: Step one, band draw at level 1500 (raw bounds 850 to 2150, TABLESAMPLE system(0.1), game limit 40)
EXPLAIN (ANALYZE, BUFFERS)
WITH foreign_games AS 
(SELECT foreign_sample.id AS id, CASE WHEN (foreign_sample.user_color = 'white') THEN foreign_sample.white_rating ELSE foreign_sample.black_rating END AS owner_rating 
FROM games AS foreign_sample TABLESAMPLE system(0.1) JOIN users ON users.id = foreign_sample.user_id 
WHERE foreign_sample.user_id != 28 AND users.is_guest IS false AND foreign_sample.platform IN ('chess.com', 'lichess') AND CASE WHEN (foreign_sample.user_color = 'white') THEN foreign_sample.white_rating ELSE foreign_sample.black_rating END BETWEEN 850 AND 2150 ORDER BY random() 
 LIMIT 40)
 SELECT game_flaws.game_id, game_flaws.ply, game_flaws.missed_pv_lines, games.platform, games.time_control_bucket, games.time_control_str, foreign_games.owner_rating 
FROM foreign_games JOIN games ON games.id = foreign_games.id JOIN game_flaws ON game_flaws.game_id = games.id AND game_flaws.user_id = games.user_id LEFT OUTER JOIN LATERAL (SELECT game_positions.eval_cp AS eval_cp, game_positions.eval_mate AS eval_mate 
FROM game_positions 
WHERE game_positions.user_id = game_flaws.user_id AND game_positions.game_id = game_flaws.game_id AND game_positions.ply = game_flaws.ply - 1 
 LIMIT 1) AS foreign_prior_position ON true 
WHERE game_flaws.severity = 2 AND NOT CASE WHEN (game_flaws.ply % 2 = 0) THEN games.user_color = 'black' ELSE games.user_color = 'white' END AND game_flaws.missed_pv_lines IS NOT NULL AND jsonb_typeof(game_flaws.missed_pv_lines) = 'array' AND game_flaws.missed_pv_lines != CAST('[]' AS JSONB) AND jsonb_typeof(game_flaws.missed_pv_lines[0]) = 'object' AND ((game_flaws.missed_pv_lines[0]) ->> 'su') IS NOT NULL AND ((game_flaws.missed_pv_lines[0]) ->> 'su') != '' AND CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'bm') AS INTEGER) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'bm') AS INTEGER) > 0) THEN 1000.0 ELSE -1000.0 END)) AS FLOAT) WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'b') AS FLOAT) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 'b') AS FLOAT))) AS FLOAT) ELSE NULL END IS NOT NULL AND CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) > 0) THEN 1000.0 ELSE -1000.0 END)) AS FLOAT) WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT))) AS FLOAT) ELSE NULL END IS NOT NULL AND (CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'bm') AS INTEGER) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'bm') AS INTEGER) > 0) THEN 1000.0 ELSE -1000.0 END)) AS FLOAT) WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'b') AS FLOAT) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 'b') AS FLOAT))) AS FLOAT) ELSE NULL END - CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) > 0) THEN 1000.0 ELSE -1000.0 END)) AS FLOAT) WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT))) AS FLOAT) ELSE NULL END >= 0.15 OR CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'bm') AS INTEGER) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'bm') AS INTEGER) > 0) THEN 1000.0 ELSE -1000.0 END)) AS FLOAT) WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'b') AS FLOAT) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 'b') AS FLOAT))) AS FLOAT) ELSE NULL END - CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CASE WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) > 0) THEN 1000.0 ELSE -1000.0 END)) AS FLOAT) WHEN (CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT) IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT))) AS FLOAT) ELSE NULL END < 0.05) AND (((game_flaws.missed_pv_lines[0]) ->> 'su') = '' OR CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) IS NOT NULL AND CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1 ELSE -1 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) < 0 OR CAST(((game_flaws.missed_pv_lines[0]) ->> 'sm') AS INTEGER) IS NULL AND (CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT) IS NULL OR CASE WHEN (CASE WHEN (game_flaws.ply % 2 = 0) THEN 'white' ELSE 'black' END = 'white') THEN 1.0 ELSE -1.0 END * CAST(((game_flaws.missed_pv_lines[0]) ->> 's') AS FLOAT) < 200)) AND CASE WHEN (foreign_prior_position.eval_mate IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (games.user_color = 'white') THEN 1.0 ELSE -1.0 END * CASE WHEN (foreign_prior_position.eval_mate > 0) THEN 1000.0 ELSE -1000.0 END)) AS FLOAT) WHEN (foreign_prior_position.eval_cp IS NOT NULL) THEN 1.0 / CAST((1.0 + exp(-0.00368208 * CASE WHEN (games.user_color = 'white') THEN 1.0 ELSE -1.0 END * foreign_prior_position.eval_cp)) AS FLOAT) ELSE NULL END >= 0.2;

